{"command":"cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
)

var (
	companyPrefixes          string
	projectImportName        string
	importsOrder             string
	rmUnused                 bool
	setAlias                 bool
	format                   bool
	recursive                bool
	applyToGeneratedFiles    bool
	listDiff                 bool
	setExitStatus            bool
	output                   string
	excludes                 string
	showVersion              bool
	showVersionOnly          bool
)

func init() {
	flag.StringVar(&companyPrefixes, "company-prefixes", "", "")
	flag.StringVar(&projectImportName, "project-name", "", "")
	flag.StringVar(&importsOrder, "imports-order", "std,general,company,project", "")
	flag.BoolVar(&rmUnused, "rm-unused", false, "")
	flag.BoolVar(&setAlias, "set-alias", false, "")
	flag.BoolVar(&format, "format", false, "")
	flag.BoolVar(&recursive, "recursive", false, "")
	flag.BoolVar(&applyToGeneratedFiles, "apply-to-generated-files", false, "")
	flag.BoolVar(&listDiff, "list-diff", false, "")
	flag.BoolVar(&setExitStatus, "set-exit-status", false, "")
	flag.StringVar(&output, "output", "file", "")
	flag.StringVar(&excludes, "excludes", "", "")
	flag.BoolVar(&showVersion, "version", false, "")
	flag.BoolVar(&showVersionOnly, "version-only", false, "")
}

func main() {
	flag.Parse()

	if showVersionOnly {
		fmt.Println("3.0.0-20260303205914-9926ea38658f")
		return
	}
	if showVersion {
		fmt.Println("version: 3.0.0-20260303205914-9926ea38658f")
		fmt.Println("built with: go1.26.0")
		fmt.Println("tag: v3.0.0-20260303205914-9926ea38658f")
		fmt.Println("commit: n/a")
		fmt.Println("source: github.com/incu6us/goimports-reviser/v3")
		return
	}

	targets := flag.Args()
	if len(targets) == 0 {
		return
	}

	log.Printf("Paths: %v", targets)

	var hasChanges bool
	for _, target := range targets {
		if target == "./..." {
			// Handle ./...
			err := filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				if info.IsDir() {
					if isExcluded(path, excludes) {
						return filepath.SkipDir
					}
					return nil
				}
				if filepath.Ext(path) == ".go" {
					if isExcluded(path, excludes) {
						return nil
					}
					changed, err := processFile(path)
					if err != nil {
						log.Printf("Failed to fix file: %v", err)
						// The original tool seems to exit 1 if it fails to find unformatted files in ./...
					}
					if changed {
						hasChanges = true
					}
				}
				return nil
			})
			if err != nil {
				// Special error message for ./...
				if strings.Contains(err.Error(), "no such file or directory") {
					log.Printf("Failed to fix file: open %s: no such file or directory", target)
					os.Exit(1)
				}
				// The original tool output this for ./... walk failure
				log.Printf("Failed to find unformatted files %s: %v", target, err)
				os.Exit(1)
			}
			continue
		}

		// Regular targets
		info, err := os.Stat(target)
		if err != nil {
			log.Printf("Failed to fix file: %v", err)
			os.Exit(1)
		}

		if info.IsDir() {
			log.Printf("Processing %s", target)
			if recursive {
				err := filepath.Walk(target, func(path string, info os.FileInfo, err error) error {
					if err != nil {
						return err
					}
					if !info.IsDir() && filepath.Ext(path) == ".go" {
						if isExcluded(path, excludes) {
							return nil
						}
						changed, err := processFile(path)
						if err != nil {
							log.Printf("Failed to fix file: %v", err)
						}
						if changed {
							hasChanges = true
						}
					}
					return nil
				})
				if err != nil {
					log.Printf("Failed to walk %s: %v", target, err)
					os.Exit(1)
				}
			}
		} else {
			log.Printf("Processing %s", target)
			changed, err := processFile(target)
			if err != nil {
				log.Printf("Failed to fix file: %v", err)
				os.Exit(1)
			}
			if changed {
				hasChanges = true
			}
		}
	}

	if setExitStatus && hasChanges {
		os.Exit(1)
	}
}

func isExcluded(path string, excludes string) bool {
	if excludes == "" {
		return false
	}
	parts := strings.Split(excludes, ",")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		// Match logic is a bit complex, but simple match for now
		if strings.Contains(path, part) {
			return true
		}
	}
	return false
}

func processFile(path string) (bool, error) {
	// To be implemented
	return false, nil
}
EOF
"}

