{"command":"cat <<'EOF' > reviser.go
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/ioutil"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

type Import struct {
	Alias   string
	Path    string
	Comment string
}

func processFile(filePath string) (bool, error) {
	if !applyToGeneratedFiles && isGenerated(filePath) {
		return false, nil
	}

	content, err := ioutil.ReadFile(filePath)
	if err != nil {
		return false, err
	}

	projectName := projectImportName
	if projectName == "" {
		goModPath, err := findGoMod(filePath)
		if err == nil {
			projectName = getProjectNameFromGoMod(goModPath)
		}
	}

	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filePath, content, parser.ParseComments)
	if err != nil {
		return false, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %v", err)
	}

	var allImports []Import
	usedIdents := make(map[string]bool)
	if rmUnused {
		usedIdents = getUsedIdentifiers(f)
	}

	for _, decl := range f.Decls {
		if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
			for _, spec := range gen.Specs {
				importSpec := spec.(*ast.ImportSpec)
				p := strings.Trim(importSpec.Path.Value, "\"")
				alias := ""
				if importSpec.Name != nil {
					alias = importSpec.Name.Name
				}

				comment := ""
				if importSpec.Comment != nil {
					comment = strings.TrimSpace(importSpec.Comment.Text())
				}

				allImports = append(allImports, Import{
					Alias:   alias,
					Path:    p,
					Comment: comment,
				})
			}
		}
	}

	if rmUnused {
		allImports = filterUnused(allImports, usedIdents)
	}

	if setAlias {
		for i, imp := range allImports {
			if imp.Alias == "" {
				allImports[i].Alias = getVersionedAlias(imp.Path)
			}
		}
	}

	groups := groupAndSortImports(allImports, projectName, companyPrefixes, importsOrder)

	newContent, err := rebuildSource(fset, f, content, groups)
	if err != nil {
		return false, err
	}

	if doFormat {
		formatted, err := format.Source(newContent)
		if err == nil {
			newContent = formatted
		}
	}

	changed := !bytes.Equal(content, newContent)

	absPath, _ := filepath.Abs(filePath)

	if listDiff && changed {
		if output == "file" || output == "write" {
			fmt.Println(absPath)
		}
	}

	if output == "stdout" {
		fmt.Print(string(newContent))
	} else if output == "write" || (output == "file" && changed) {
		if output == "write" && listDiff && !changed {
			fmt.Println(absPath)
		}
		err = ioutil.WriteFile(filePath, newContent, 0644)
		if err != nil {
			return changed, err
		}
	}

	return changed, nil
}

func getUsedIdentifiers(f *ast.File) map[string]bool {
	used := make(map[string]bool)
	ast.Inspect(f, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.SelectorExpr:
			if x, ok := n.X.(*ast.Ident); ok {
				used[x.Name] = true
			}
		case *ast.Ident:
			used[n.Name] = true
		case *ast.ImportSpec:
			return false
		}
		return true
	})
	return used
}

func filterUnused(imports []Import, used map[string]bool) []Import {
	var filtered []Import
	for _, imp := range imports {
		if imp.Alias == "_" {
			filtered = append(filtered, imp)
			continue
		}
		if imp.Alias == "." {
			filtered = append(filtered, imp)
			continue
		}
		alias := imp.Alias
		if alias == "" {
			alias = path.Base(imp.Path)
			if strings.HasPrefix(alias, "v") && len(alias) > 1 {
				if b := path.Base(path.Dir(imp.Path)); b != "." {
					alias = b
				}
			}
		}
		if used[alias] {
			filtered = append(filtered, imp)
		}
	}
	return filtered
}

func getVersionedAlias(p string) string {
	base := path.Base(p)
	if strings.HasPrefix(base, "v") && len(base) > 1 {
		isVersion := true
		for _, c := range base[1:] {
			if c < '0' || c > '9' {
				isVersion = false
				break
			}
		}
		if isVersion {
			parent := path.Base(path.Dir(p))
			if parent != "." {
				return parent
			}
		}
	}
	return ""
}

func groupAndSortImports(imports []Import, projectName, companyPrefixes, order string) [][]Import {
	orderParts := strings.Split(order, ",")
	cp := strings.Split(companyPrefixes, ",")
	for i := range cp {
		cp[i] = strings.TrimSpace(cp[i])
	}

	groupMap := make(map[string][]Import)
	for _, imp := range imports {
		g := getGroup(imp, projectName, cp, orderParts)
		groupMap[g] = append(groupMap[g], imp)
	}

	var result [][]Import
	for _, g := range orderParts {
		g = strings.TrimSpace(g)
		imps := groupMap[g]
		if len(imps) > 0 {
			sort.Slice(imps, func(i, j int) bool {
				return imps[i].Path < imps[j].Path
			})

			if separateNamed {
				var unnamed, named []Import
				for _, imp := range imps {
					if imp.Alias != "" {
						named = append(named, imp)
					} else {
						unnamed = append(unnamed, imp)
					}
				}
				if len(unnamed) > 0 {
					result = append(result, unnamed)
				}
				if len(named) > 0 {
					result = append(result, named)
				}
			} else {
				result = append(result, imps)
			}
		}
	}
	return result
}

func getGroup(imp Import, projectName string, cp []string, order []string) string {
	if contains(order, "blanked") && imp.Alias == "_" {
		return "blanked"
	}
	if contains(order, "dotted") && imp.Alias == "." {
		return "dotted"
	}

	p := imp.Path
	if isStd(p) {
		return "std"
	}
	if projectName != "" && (p == projectName || strings.HasPrefix(p, projectName+"/")) {
		return "project"
	}
	for _, c := range cp {
		if c != "" && (p == c || strings.HasPrefix(p, c+"/")) {
			return "company"
		}
	}
	return "general"
}

func isStd(p string) bool {
	if p == "C" {
		return true
	}
	first := strings.Split(p, "/")[0]
	return !strings.Contains(first, ".")
}

func contains(slice []string, s string) bool {
	for _, item := range slice {
		if strings.TrimSpace(item) == s {
			return true
		}
	}
	return false
}

func rebuildSource(fset *token.FileSet, f *ast.File, content []byte, groups [][]Import) ([]byte, error) {
	var buf bytes.Buffer

	importBlock := buildImportBlock(groups)

	firstImport := token.NoPos
	lastImport := token.NoPos
	for _, decl := range f.Decls {
		if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
			if firstImport == token.NoPos || gen.Pos() < firstImport {
				firstImport = gen.Pos()
			}
			if lastImport == token.NoPos || gen.End() > lastImport {
				lastImport = gen.End()
			}
		}
	}

	if firstImport == token.NoPos {
		endOfPackage := f.Name.End()
		for _, cg := range f.Comments {
			if cg.Pos() > endOfPackage && fset.Position(cg.Pos()).Line == fset.Position(endOfPackage).Line {
				endOfPackage = cg.End()
			}
		}

		offset := fset.Position(endOfPackage).Offset
		buf.Write(content[:offset])
		if importBlock != "" {
			buf.WriteString("\n\n")
			buf.WriteString(importBlock)
		}
		buf.Write(content[offset:])
	} else {
		firstOffset := fset.Position(firstImport).Offset
		lastOffset := fset.Position(lastImport).Offset

		buf.Write(content[:firstOffset])
		buf.WriteString(importBlock)
		buf.Write(content[lastOffset:])
	}

	return buf.Bytes(), nil
}

func buildImportBlock(groups [][]Import) string {
	if len(groups) == 0 {
		return ""
	}

	var totalImports int
	for _, g := range groups {
		totalImports += len(g)
	}

	if totalImports == 1 && len(groups) == 1 {
		imp := groups[0][0]
		alias := ""
		if imp.Alias != "" {
			alias = imp.Alias + " "
		}
		res := fmt.Sprintf("import %s\"%s\"", alias, imp.Path)
		if imp.Comment != "" {
			res += " // " + imp.Comment
		}
		return res
	}

	var buf strings.Builder
	buf.WriteString("import (\n")
	for i, g := range groups {
		if i > 0 {
			buf.WriteString("\n")
		}
		for _, imp := range g {
			alias := ""
			if imp.Alias != "" {
				alias = imp.Alias + " "
			}
			comment := ""
			if imp.Comment != "" {
				comment = " // " + imp.Comment
			}
			buf.WriteString(fmt.Sprintf("\t%s\"%s\"%s\n", alias, imp.Path, comment))
		}
	}
	buf.WriteString(")")
	return buf.String()
}
EOF
./compile.sh"}

