	setAlias                 bool
	doFormat                 bool
	recursive                bool
	applyToGeneratedFiles    bool
	listDiff                 bool
	setExitStatus            bool
	output                   string
	excludes                 string
	showVersion              bool
	showVersionOnly          bool
	separateNamed            bool
	useCache                 bool
	local                    string
	filePathDeprecated       string
)

func init() {
	flag.BoolVar(&applyToGeneratedFiles, "apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	flag.StringVar(&companyPrefixes, "company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	flag.StringVar(&excludes, "excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	flag.StringVar(&filePathDeprecated, "file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	flag.BoolVar(&doFormat, "format", false, "Option will perform additional formatting. Optional parameter.")
	flag.StringVar(&importsOrder, "imports-order", "std,general,company,project", "Your imports groups can be sorted in your way.\nstd - std import group;\ngeneral - libs for general purpose;\ncompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs);\nproject - your local project dependencies;\nblanked - imports with \"_\" alias;\ndotted - imports with \".\" alias.\nOptional parameter.")
	flag.BoolVar(&listDiff, "list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	flag.StringVar(&local, "local", "", "Deprecated")
	flag.StringVar(&output, "output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	flag.StringVar(&projectImportName, "project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	flag.BoolVar(&recursive, "recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	flag.BoolVar(&rmUnused, "rm-unused", false, "Remove unused imports. Optional parameter.")
	flag.BoolVar(&separateNamed, "separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	flag.BoolVar(&setAlias, "set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	flag.BoolVar(&setExitStatus, "set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	flag.BoolVar(&useCache, "use-cache", false, "Use cache to improve performance. Optional parameter.")
	flag.BoolVar(&showVersion, "version", false, "Show version information")
	flag.BoolVar(&showVersionOnly, "version-only", false, "Show only the version string")
}

func main() {
	flag.Parse()

	if showVersionOnly {
		fmt.Println("3.0.0-20260303205914-9926ea38658f")
		return
	}
	if showVersion {
