			err := filepath.Walk(target, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				if !info.IsDir() && filepath.Ext(path) == ".go" {
					if isExcluded(path, excludes) {
						return nil
					}
					if !recursive && filepath.Dir(path) != target {
						return filepath.SkipDir
					}
					changed, err := processFile(path)
					if err != nil {
						log.Printf("Failed to fix file: %v", err)
					}
					if changed {
						hasChanges = true
					}
				}
				return nil
			})
			if err != nil {
				log.Printf("Failed to walk %s: %v", target, err)
				os.Exit(1)
			}
		} else {
			log.Printf("Processing %s", target)
			changed, err := processFile(target)
			if err != nil {
				log.Printf("Failed to fix file: %v", err)
				os.Exit(1)
			}
			if changed {
				hasChanges = true
			}
		}
	}

	if setExitStatus && hasChanges {
		os.Exit(1)
	}
}

func isExcluded(path string, excludes string) bool {
	if excludes == "" {
		return false
	}
	parts := strings.Split(excludes, ",")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if strings.Contains(path, part) {
			return true
		}
	}
	return false
}
