	}

	var totalImports int
	for _, g := range groups {
		totalImports += len(g)
	}

	if totalImports == 1 && len(groups) == 1 {
		imp := groups[0][0]
		alias := ""
		if imp.Alias != "" {
			alias = imp.Alias + " "
		}
		res := fmt.Sprintf("import %s\"%s\"", alias, imp.Path)
		if imp.Comment != "" {
			res += " // " + imp.Comment
		}
		return res
	}

	var buf strings.Builder
	buf.WriteString("import (\n")
	for i, g := range groups {
		if i > 0 {
			buf.WriteString("\n")
		}
		for _, imp := range g {
			alias := ""
			if imp.Alias != "" {
				alias = imp.Alias + " "
			}
			comment := ""
			if imp.Comment != "" {
				comment = " // " + imp.Comment
			}
			buf.WriteString(fmt.Sprintf("\t%s\"%s\"%s\n", alias, imp.Path, comment))
		}
	}
	buf.WriteString(")")
	return buf.String()
}
EOF
